use crate::{model::{Expr,Model,Var,Row,parse_q,Q},proof::*,verify::{verify,Limits},codec,rpa};
fn q(s:&str)->Q{parse_q(s).unwrap()}
fn e(c:&str,terms:&[(u32,&str)])->Expr{Expr{constant:q(c),terms:terms.iter().map(|(i,c)|(*i,q(c))).collect()}}
fn model(integer:bool)->Model{Model{name:"tiny".into(),vars:vec![Var{name:"x".into(),integer,lower:Some(q("0")),upper:Some(q("1"))}],rows:vec![Row{name:"r".into(),expr:e("0",&[(0,"1")]),lower:None,upper:Some(q("1"))}],objective:e("0",&[(0,"1")])}}
fn identity()->Certificate{let b=Block{steps:vec![],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::VarLower(0),Ref::VarUpper(0),Ref::VarInt(0),Ref::RowUpper(0),Ref::Exact]}};Certificate{forward:b.clone(),reverse:b}}
fn ok(s:&Model,t:&Model,c:&Certificate)->bool{crate::verify::check_block(s,t,&c.forward,&Limits::default()).is_ok()}
#[test]fn actual_binary_identity_roundtrip(){let m=model(true);let cert=identity();let m=codec::decode_model(&codec::encode_model(&m).unwrap()).unwrap();let cert=codec::decode_certificate(&codec::encode_certificate(&cert).unwrap()).unwrap();assert!(ok(&m,&m,&cert));assert_eq!(rpa::assemble(&rpa::disassemble(&cert).unwrap()).unwrap(),cert);}
#[test]fn full_model_binding(){let m=model(true);let c=identity();let mut t=m.clone();t.objective.constant=q("1");assert!(!ok(&m,&t,&c));t=m.clone();t.vars[0].upper=Some(q("0"));assert!(!ok(&m,&t,&c));t=m.clone();t.rows[0].upper=Some(q("0"));assert!(!ok(&m,&t,&c));}
#[test]fn missing_extra_and_wrong_mapping(){let m=model(true);let mut c=identity();if let End::Return{checks,..}=&mut c.forward.end{checks.pop();}assert!(!ok(&m,&m,&c));let mut c=identity();if let End::Return{checks,..}=&mut c.forward.end{checks.push(Ref::Exact);}assert!(!ok(&m,&m,&c));let mut c=identity();if let End::Return{map,..}=&mut c.forward.end{map[0]=e("0",&[]);}assert!(!ok(&m,&m,&c));}
#[test]fn integer_facts_require_actual_integer_variables(){let m=model(false);assert!(!ok(&m,&m,&identity()));}
#[test]fn exact_negative_rounding(){let mut s=model(true);s.vars[0].lower=Some(q("-5"));s.vars[0].upper=Some(q("5"));s.rows[0].upper=Some(q("-1.5"));let mut t=s.clone();t.rows[0].upper=Some(q("-2"));let mut c=identity();c.forward.steps.push(Step::Round{id:0,le:Ref::RowUpper(0),integer:Ref::VarInt(0)});if let End::Return{checks,..}=&mut c.forward.end{checks[3]=Ref::Local(0);}assert!(ok(&s,&t,&c));t.rows[0].upper=Some(q("-3"));assert!(!ok(&s,&t,&c));}
#[test]fn fractional_integer_multiplier_rejected(){let m=model(true);let mut c=identity();c.forward.steps.push(Step::Lin{id:3,kind:Kind::Int,constant:q("0"),terms:vec![(Ref::VarInt(0),q("1/2"))]});assert!(!ok(&m,&m,&c));}
#[test]fn invalid_middle_linear_reference(){let m=model(true);let mut c=identity();c.forward.steps.push(Step::Lin{id:3,kind:Kind::Le,constant:q("0"),terms:vec![(Ref::VarLower(0),q("1")),(Ref::Local(77),q("0")),(Ref::VarUpper(0),q("1"))]});assert!(!ok(&m,&m,&c));}
#[test]fn dead_fact_and_overwrite_rejected(){let m=model(true);let lin=Step::Lin{id:1,kind:Kind::Le,constant:q("0"),terms:vec![(Ref::VarLower(0),q("1"))]};let mut c=identity();c.forward.steps=vec![lin.clone(),lin.clone()];assert!(!ok(&m,&m,&c));c.forward.steps=vec![lin,Step::Drop{ids:vec![1]}];if let End::Return{checks,..}=&mut c.forward.end{checks[0]=Ref::Local(1);}assert!(!ok(&m,&m,&c));}
#[test]fn real_piecewise_common_map_and_sibling_isolation(){
 let mut s=model(false);s.vars[0].lower=Some(q("-1"));s.rows.clear();s.objective=Expr::zero();let mut t=s.clone();t.vars[0].lower=Some(q("0"));
 let left=Block{steps:vec![Step::Lin{id:9,kind:Kind::Le,constant:q("0"),terms:vec![(Ref::Assumption(0),q("1"))]}],end:End::Return{map:vec![e("0",&[(0,"-1")])],checks:vec![Ref::Local(9),Ref::VarLower(0),Ref::Exact]}};
 let right=Block{steps:vec![],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::Assumption(0),Ref::VarUpper(0),Ref::Exact]}};
 let mut c=identity();c.forward=Block{steps:vec![],end:End::Split{expression:Expr::var(0),integer:None,left:Box::new(left),right:Box::new(right)}};
 assert!(ok(&s,&t,&c));if let End::Split{right,..}=&mut c.forward.end{if let End::Return{checks,..}=&mut right.end{checks[0]=Ref::Local(9);}}assert!(!ok(&s,&t,&c));
}
#[test]fn contradiction_is_checked_and_handles_infeasible_model(){let mut s=model(true);s.vars[0].lower=Some(q("2"));let t=model(true);let mut c=identity();c.forward=Block{steps:vec![Step::Lin{id:0,kind:Kind::Le,constant:q("0"),terms:vec![(Ref::VarLower(0),q("1")),(Ref::VarUpper(0),q("1"))]}],end:End::Absurd{fact:Ref::Local(0)}};assert!(ok(&s,&t,&c));s.vars[0].lower=Some(q("0"));assert!(!ok(&s,&t,&c));}
#[test]fn budget_exhaustion_is_distinct(){let m=model(true);let c=identity();let limits=Limits{work:1,..Limits::default()};assert!(verify(&m,&m,&c,&limits).unwrap_err().starts_with("RESOURCE_LIMIT"));}
#[test]fn rpa_strict_fields_version_and_numbers(){assert!(rpa::assemble("RPA 0.1\n{}").is_err());let text=rpa::disassemble(&identity()).unwrap().replace("\"steps\": []","\"steps\": [], \"unrecognized\": true");assert!(rpa::assemble(&text).is_err());}
